def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from fractions import Fraction

    jump = {a: b for a, b in jumps}

    def destination(cell: int) -> int:
        path = []
        while cell in jump:
            path.append(cell)
            cell = jump[cell]
        for start in path:
            jump[start] = cell
        return cell

    transitions = {}
    reachable = {0}
    pending = [0]

    while pending:
        cell = pending.pop()
        if cell == n:
            continue
        counts = {}
        for roll in range(1, m + 1):
            target = cell + roll
            if target > n:
                target = 2 * n - target
            target = destination(target)
            counts[target] = counts.get(target, 0) + 1
            if target not in reachable:
                reachable.add(target)
                pending.append(target)
        transitions[cell] = counts

    reverse = {cell: [] for cell in reachable}
    for cell, counts in transitions.items():
        for target in counts:
            reverse[target].append(cell)

    can_finish = {n} if n in reachable else set()
    pending = list(can_finish)
    while pending:
        cell = pending.pop()
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                pending.append(previous)

    if len(can_finish) != len(reachable):
        return None

    states = [cell for cell in reachable if cell != n]
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]

    for cell in states:
        i = index[cell]
        matrix[i][i] = m
        matrix[i][size] = m
        for target, count in transitions[cell].items():
            if target != n:
                matrix[i][index[target]] -= count

    # Fraction-free Gaussian elimination.
    previous_pivot = 1
    for col in range(size - 1):
        if matrix[col][col] == 0:
            for row in range(col + 1, size):
                if matrix[row][col] != 0:
                    matrix[col], matrix[row] = matrix[row], matrix[col]
                    break

        pivot = matrix[col][col]
        for row in range(col + 1, size):
            factor = matrix[row][col]
            for j in range(col + 1, size + 1):
                matrix[row][j] = (
                    matrix[row][j] * pivot - factor * matrix[col][j]
                ) // previous_pivot
            matrix[row][col] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * solution[j]
        solution[i] = value / matrix[i][i]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
